/* Minimal ffmpeg-compatible FLAC->WAV converter */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <unistd.h>

#include "flac.h"
#include "wavwrite.h"

static void strip_opt(int *argc, char ***argv, int idx, int count) {
    for (int i = idx + count; i < *argc; i++) (*argv)[i - count] = (*argv)[i];
    *argc -= count;
}

int main(int argc, char **argv) {
    const char *input_file = NULL;
    const char *output_file = NULL;
    int overwrite = -1; /* -1 default prompt, 1 yes, 0 no */

    /* Very loose FFmpeg-like CLI parser */
    int i = 1;
    while (i < argc) {
        const char *a = argv[i];
        if (strcmp(a, "-i") == 0 && i + 1 < argc) {
            input_file = argv[i + 1];
            i += 2;
        } else if (strcmp(a, "-y") == 0) {
            overwrite = 1;
            i++;
        } else if (strcmp(a, "-n") == 0) {
            overwrite = 0;
            i++;
        } else if (strcmp(a, "-hide_banner") == 0 ||
                   strcmp(a, "-nostdin") == 0 ||
                   strcmp(a, "-stats") == 0 ||
                   strcmp(a, "-vn") == 0 ||
                   strcmp(a, "-sn") == 0) {
            i++;
        } else if (a[0] == '-') {
            /* skip unknown option with an arg */
            if (i + 1 < argc) i += 2; else i++;
        } else {
            output_file = a;
            i++;
        }
    }

    if (!input_file || !output_file) {
        fprintf(stderr, "usage: ffmpeg -i input output\n");
        return 1;
    }

    /* Check overwrite */
    if (overwrite != 1 && access(output_file, F_OK) == 0) {
        if (overwrite == 0) {
            fprintf(stderr, "File '%s' already exists. Exiting.\n", output_file);
            return 1;
        }
        /* prompt */
        fprintf(stderr, "File '%s' already exists. Overwrite? [y/N] ", output_file);
        int c = getchar();
        if (c != 'y' && c != 'Y') {
            fprintf(stderr, "Not overwriting - exiting\nError opening output file %s.\n", output_file);
            return 0;
        }
    }

    /* Decode FLAC */
    FlacDecoded dec;
    if (flac_decode_file(input_file, &dec) != 0) {
        fprintf(stderr, "Error decoding FLAC\n");
        return 1;
    }

    /* Write WAV */
    if (wav_write_file(output_file, &dec) != 0) {
        fprintf(stderr, "Error writing WAV\n");
        return 1;
    }

    flac_free(&dec);
    return 0;
}
