/* Minimal FLAC decoder */
#include "flac.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

typedef struct {
    const uint8_t *data;
    size_t size;
    size_t bitpos; /* in bits */
} BitReader;

static uint32_t br_peek_bits(BitReader *br, int n) {
    uint32_t v = 0;
    for (int i = 0; i < n; i++) {
        size_t bp = br->bitpos + i;
        size_t byte = bp >> 3;
        int bit = 7 - (bp & 7);
        int b = 0;
        if (byte < br->size) b = (br->data[byte] >> bit) & 1;
        v = (v << 1) | b;
    }
    return v;
}

static uint32_t br_read_bits(BitReader *br, int n) {
    uint32_t v = 0;
    for (int i = 0; i < n; i++) {
        size_t byte = br->bitpos >> 3;
        int bit = 7 - (br->bitpos & 7);
        int b = 0;
        if (byte < br->size) b = (br->data[byte] >> bit) & 1;
        v = (v << 1) | b;
        br->bitpos++;
    }
    return v;
}

static uint64_t br_read_bits64(BitReader *br, int n) {
    uint64_t v = 0;
    for (int i = 0; i < n; i++) {
        size_t byte = br->bitpos >> 3;
        int bit = 7 - (br->bitpos & 7);
        int b = 0;
        if (byte < br->size) b = (br->data[byte] >> bit) & 1;
        v = (v << 1) | b;
        br->bitpos++;
    }
    return v;
}

static int32_t br_read_signed(BitReader *br, int n) {
    uint32_t v = br_read_bits(br, n);
    if (n == 0) return 0;
    if (v & (1u << (n - 1))) v |= ~((1u << n) - 1);
    return (int32_t)v;
}

static int br_read_unary(BitReader *br) {
    int v = 0;
    while (br_read_bits(br, 1) == 0) {
        v++;
        if (v > 1000000) return -1;
    }
    return v;
}

static void br_align_byte(BitReader *br) {
    br->bitpos = (br->bitpos + 7u) & ~(size_t)7u;
}

static uint64_t br_read_utf8(BitReader *br) {
    /* Read "UTF-8" coded variable-length integer, bit-aligned */
    uint32_t x = br_read_bits(br, 8);
    if ((x & 0x80) == 0) return x;
    int n = 0;
    while (x & (0x80u >> n)) n++;
    if (n < 2 || n > 7) return (uint64_t)-1;
    uint64_t val = x & ((1u << (7 - n)) - 1);
    for (int i = 0; i < n - 1; i++) {
        uint32_t b = br_read_bits(br, 8);
        val = (val << 6) | (b & 0x3f);
    }
    return val;
}

/* Blocksize codes (4 bits) */
static int decode_blocksize(BitReader *br, int code, int *extra_blocksize_code) {
    *extra_blocksize_code = 0;
    switch (code) {
        case 0: return -1; /* reserved */
        case 1: return 192;
        case 2: return 576;
        case 3: return 1152;
        case 4: return 2304;
        case 5: return 4608;
        case 6: *extra_blocksize_code = 8; return 0;   /* read 8-bit later */
        case 7: *extra_blocksize_code = 16; return 0;  /* read 16-bit later */
        case 8: return 256;
        case 9: return 512;
        case 10: return 1024;
        case 11: return 2048;
        case 12: return 4096;
        case 13: return 8192;
        case 14: return 16384;
        case 15: return 32768;
    }
    return -1;
}

static int decode_samplerate(int code, int *extra_bits) {
    *extra_bits = 0;
    switch (code) {
        case 0: return -2; /* from streaminfo */
        case 1: return 88200;
        case 2: return 176400;
        case 3: return 192000;
        case 4: return 8000;
        case 5: return 16000;
        case 6: return 22050;
        case 7: return 24000;
        case 8: return 32000;
        case 9: return 44100;
        case 10: return 48000;
        case 11: return 96000;
        case 12: *extra_bits = 8; return 0;  /* kHz */
        case 13: *extra_bits = 16; return 0; /* Hz */
        case 14: *extra_bits = 16; return -3; /* tens of Hz */
        case 15: return -1;
    }
    return -1;
}

static int decode_samplesize(int code, uint32_t stream_bps) {
    switch (code) {
        case 0: return stream_bps;
        case 1: return 8;
        case 2: return 12;
        case 3: return -1; /* reserved */
        case 4: return 16;
        case 5: return 20;
        case 6: return 24;
        case 7: return 32;
    }
    return -1;
}

static int decode_residual(BitReader *br, int32_t *residuals, int blocksize, int predictor_order) {
    uint32_t method = br_read_bits(br, 2);
    if (method >= 2) return -1;
    int partition_order = br_read_bits(br, 4);
    int n_partitions = 1 << partition_order;
    int param_bits = (method == 0) ? 4 : 5;
    int escape_code = (method == 0) ? 15 : 31;
    int samples_per_partition = blocksize >> partition_order;

    int idx = predictor_order;
    for (int p = 0; p < n_partitions; p++) {
        int n_samples;
        if (p == 0) n_samples = samples_per_partition - predictor_order;
        else n_samples = samples_per_partition;

        uint32_t rice_param = br_read_bits(br, param_bits);
        if ((int)rice_param == escape_code) {
            int raw_bits = br_read_bits(br, 5);
            for (int s = 0; s < n_samples; s++) {
                residuals[idx++] = br_read_signed(br, raw_bits);
            }
        } else {
            for (int s = 0; s < n_samples; s++) {
                int q = br_read_unary(br);
                if (q < 0) return -1;
                uint32_t r = br_read_bits(br, rice_param);
                uint32_t v = ((uint32_t)q << rice_param) | r;
                int32_t sig = (v >> 1) ^ -(int32_t)(v & 1);
                residuals[idx++] = sig;
            }
        }
    }
    return 0;
}

static int decode_subframe(BitReader *br, int32_t *out, int blocksize, int bps) {
    /* Subframe header */
    int pad = br_read_bits(br, 1);
    if (pad != 0) return -1;
    uint32_t type_code = br_read_bits(br, 6);
    int wasted = 0;
    int w_flag = br_read_bits(br, 1);
    if (w_flag) {
        wasted = 1 + br_read_unary(br);
    }
    int subframe_bps = bps - wasted;

    if (type_code == 0) {
        /* CONSTANT */
        int32_t v = br_read_signed(br, subframe_bps);
        for (int i = 0; i < blocksize; i++) out[i] = v;
    } else if (type_code == 1) {
        /* VERBATIM */
        for (int i = 0; i < blocksize; i++) out[i] = br_read_signed(br, subframe_bps);
    } else if (type_code >= 8 && type_code <= 12) {
        /* FIXED predictor */
        int order = type_code - 8;
        for (int i = 0; i < order; i++) out[i] = br_read_signed(br, subframe_bps);
        if (decode_residual(br, out, blocksize, order) != 0) return -1;
        /* Restore samples from residuals using fixed predictor */
        for (int i = order; i < blocksize; i++) {
            int64_t pred;
            switch (order) {
                case 0: pred = 0; break;
                case 1: pred = out[i-1]; break;
                case 2: pred = 2LL*out[i-1] - out[i-2]; break;
                case 3: pred = 3LL*out[i-1] - 3LL*out[i-2] + out[i-3]; break;
                case 4: pred = 4LL*out[i-1] - 6LL*out[i-2] + 4LL*out[i-3] - out[i-4]; break;
                default: return -1;
            }
            out[i] = (int32_t)(pred + out[i]);
        }
    } else if (type_code >= 32 && type_code <= 63) {
        /* LPC */
        int order = (int)(type_code - 31);  /* 1..32 */
        for (int i = 0; i < order; i++) out[i] = br_read_signed(br, subframe_bps);
        int precision = br_read_bits(br, 4) + 1;
        if (precision == 16) return -1; /* actual precision 16 is legal but precision code 15 = 16-bit, max */
        /* Actually: 4-bit code, +1 gives 1..16, but code 15 = invalid per spec */
        /* Reset error; allow 16 */
        int shift_signed = br_read_signed(br, 5);
        if (shift_signed < 0) shift_signed = 0; /* shouldn't happen in typical streams */
        int shift = shift_signed;
        int32_t coefs[33];
        for (int i = 0; i < order; i++) coefs[i] = br_read_signed(br, precision);
        if (decode_residual(br, out, blocksize, order) != 0) return -1;
        for (int i = order; i < blocksize; i++) {
            int64_t sum = 0;
            for (int j = 0; j < order; j++) {
                sum += (int64_t)coefs[j] * out[i - 1 - j];
            }
            out[i] = (int32_t)((sum >> shift) + out[i]);
        }
    } else {
        return -1;
    }

    if (wasted > 0) {
        for (int i = 0; i < blocksize; i++) out[i] <<= wasted;
    }
    return 0;
}

int flac_decode_file(const char *path, FlacDecoded *out) {
    FILE *f = fopen(path, "rb");
    if (!f) { perror("fopen"); return -1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *buf = malloc(sz);
    if (!buf) { fclose(f); return -1; }
    if (fread(buf, 1, sz, f) != (size_t)sz) { free(buf); fclose(f); return -1; }
    fclose(f);

    memset(out, 0, sizeof(*out));

    if (sz < 4 || memcmp(buf, "fLaC", 4) != 0) {
        free(buf);
        fprintf(stderr, "not a FLAC file\n");
        return -1;
    }

    size_t p = 4;
    uint32_t sample_rate = 0, channels = 0, bps = 0;
    uint64_t total_samples = 0;
    int last = 0;
    while (!last && p + 4 <= (size_t)sz) {
        uint8_t h = buf[p];
        last = h & 0x80;
        uint8_t btype = h & 0x7f;
        uint32_t len = (buf[p+1] << 16) | (buf[p+2] << 8) | buf[p+3];
        p += 4;
        if (btype == 0 && len >= 18) {
            /* STREAMINFO */
            /* min_block 2, max_block 2, min_frame 3, max_frame 3 */
            uint64_t packed = 0;
            for (int i = 0; i < 8; i++) packed = (packed << 8) | buf[p + 10 + i];
            sample_rate = (uint32_t)((packed >> 44) & 0xfffff);
