static int decode_residual(BitReader *br, int32_t *residuals, int blocksize, int predictor_order) {
    uint32_t method = br_read_bits(br, 2);
    if (method >= 2) return -1;
    int partition_order = br_read_bits(br, 4);
    int n_partitions = 1 << partition_order;
    int param_bits = (method == 0) ? 4 : 5;
    int escape_code = (method == 0) ? 15 : 31;
    int samples_per_partition = blocksize >> partition_order;

    int idx = predictor_order;
    for (int p = 0; p < n_partitions; p++) {
        int n_samples;
        if (p == 0) n_samples = samples_per_partition - predictor_order;
        else n_samples = samples_per_partition;

