        if ((int)rice_param == escape_code) {
            int raw_bits = br_read_bits(br, 5);
            for (int s = 0; s < n_samples; s++) {
                residuals[idx++] = br_read_signed(br, raw_bits);
            }
        } else {
            for (int s = 0; s < n_samples; s++) {
                int q = br_read_unary(br);
                if (q < 0) return -1;
                uint32_t r = br_read_bits(br, rice_param);
                uint32_t v = ((uint32_t)q << rice_param) | r;
                int32_t sig = (v >> 1) ^ -(int32_t)(v & 1);
                residuals[idx++] = sig;
            }
        }
    }
    return 0;
}

static int decode_subframe(BitReader *br, int32_t *out, int blocksize, int bps) {
