        if (shift_signed < 0) shift_signed = 0; /* shouldn't happen in typical streams */
        int shift = shift_signed;
        int32_t coefs[33];
        for (int i = 0; i < order; i++) coefs[i] = br_read_signed(br, precision);
        if (decode_residual(br, out, blocksize, order) != 0) return -1;
        for (int i = order; i < blocksize; i++) {
            int64_t sum = 0;
            for (int j = 0; j < order; j++) {
                sum += (int64_t)coefs[j] * out[i - 1 - j];
            }
            out[i] = (int32_t)((sum >> shift) + out[i]);
        }
    } else {
        return -1;
    }

    if (wasted > 0) {
        for (int i = 0; i < blocksize; i++) out[i] <<= wasted;
    }
    return 0;
}

int flac_decode_file(const char *path, FlacDecoded *out) {
    FILE *f = fopen(path, "rb");
    if (!f) { perror("fopen"); return -1; }
    fseek(f, 0, SEEK_END);
    long sz = ftell(f);
    fseek(f, 0, SEEK_SET);
    uint8_t *buf = malloc(sz);
    if (!buf) { fclose(f); return -1; }
    if (fread(buf, 1, sz, f) != (size_t)sz) { free(buf); fclose(f); return -1; }
    fclose(f);

    memset(out, 0, sizeof(*out));

    if (sz < 4 || memcmp(buf, "fLaC", 4) != 0) {
        free(buf);
        fprintf(stderr, "not a FLAC file\n");
        return -1;
    }

    size_t p = 4;
    uint32_t sample_rate = 0, channels = 0, bps = 0;
    uint64_t total_samples = 0;
    int last = 0;
    while (!last && p + 4 <= (size_t)sz) {
        uint8_t h = buf[p];
        last = h & 0x80;
        uint8_t btype = h & 0x7f;
        uint32_t len = (buf[p+1] << 16) | (buf[p+2] << 8) | buf[p+3];
        p += 4;
        if (btype == 0 && len >= 18) {
            /* STREAMINFO */
            /* min_block 2, max_block 2, min_frame 3, max_frame 3 */
            uint64_t packed = 0;
            for (int i = 0; i < 8; i++) packed = (packed << 8) | buf[p + 10 + i];
            sample_rate = (uint32_t)((packed >> 44) & 0xfffff);
            channels = (uint32_t)((packed >> 41) & 7) + 1;
            bps = (uint32_t)((packed >> 36) & 0x1f) + 1;
            total_samples = packed & (((uint64_t)1 << 36) - 1);
        }
        p += len;
    }
    if (p > (size_t)sz) { free(buf); return -1; }

    out->sample_rate = sample_rate;
    out->channels = channels;
    out->bps = bps;
    out->total_samples = total_samples;

    /* Allocate sample buffers (use total_samples as upper bound) */
    out->samples = malloc(sizeof(int32_t*) * channels);
    for (uint32_t c = 0; c < channels; c++) {
        out->samples[c] = malloc(sizeof(int32_t) * (total_samples + 1024));
        if (!out->samples[c]) { free(buf); return -1; }
    }
    out->n_samples = 0;

    BitReader br = { buf + p, (size_t)sz - p, 0 };

    /* Temp per-channel subframe buffer */
    int32_t *sub[8] = {0};
    int max_bs = 65536;
    for (uint32_t c = 0; c < channels; c++) sub[c] = malloc(sizeof(int32_t) * max_bs);

    while (out->n_samples < total_samples) {
        /* Try to find the next frame sync */
        /* Align to byte boundary */
        br_align_byte(&br);
        if (br.bitpos + 16 > br.size * 8) break;

        /* Read frame header */
        uint32_t sync = br_read_bits(&br, 14);
        if (sync != 0x3ffe) {
            /* Re-sync: step forward 1 byte and try again */
            /* For well-formed streams this shouldn't happen */
            break;
        }
        int reserved = br_read_bits(&br, 1);
        (void)reserved;
        int blocking = br_read_bits(&br, 1);
        int bs_code = br_read_bits(&br, 4);
        int sr_code = br_read_bits(&br, 4);
        int ch_code = br_read_bits(&br, 4);
        int ss_code = br_read_bits(&br, 3);
        int rsvd2 = br_read_bits(&br, 1); (void)rsvd2;

        /* UTF-8 encoded sample or frame number */
        uint64_t frame_number = br_read_utf8(&br);
        (void)frame_number;

        int extra_bs = 0;
        int blocksize = decode_blocksize(&br, bs_code, &extra_bs);
        int extra_sr = 0;
        int samplerate = decode_samplerate(sr_code, &extra_sr);
        (void)samplerate; (void)blocking;

        if (extra_bs == 8) blocksize = br_read_bits(&br, 8) + 1;
        else if (extra_bs == 16) blocksize = br_read_bits(&br, 16) + 1;

        if (extra_sr == 8) (void)br_read_bits(&br, 8);
        else if (extra_sr == 16) (void)br_read_bits(&br, 16);

        (void)br_read_bits(&br, 8); /* CRC-8 of header */

        int sample_size = decode_samplesize(ss_code, bps);
        if (sample_size < 0) break;

        int n_ch = channels;
        /* Decode subframes based on channel assignment */
        if (ch_code < 8) {
            /* Independent channels - ch_code + 1 channels */
            /* Actually ch_code is number of channels - 1 */
            n_ch = ch_code + 1;
            for (int c = 0; c < n_ch; c++) {
                if (decode_subframe(&br, sub[c], blocksize, sample_size) != 0) goto err;
            }
        } else if (ch_code == 8) {
            /* Left/Side stereo */
            if (decode_subframe(&br, sub[0], blocksize, sample_size) != 0) goto err;
            if (decode_subframe(&br, sub[1], blocksize, sample_size + 1) != 0) goto err;
            for (int i = 0; i < blocksize; i++) sub[1][i] = sub[0][i] - sub[1][i];
            n_ch = 2;
        } else if (ch_code == 9) {
            /* Right/Side stereo */
            if (decode_subframe(&br, sub[1], blocksize, sample_size + 1) != 0) goto err;
            if (decode_subframe(&br, sub[0], blocksize, sample_size) != 0) goto err;
            for (int i = 0; i < blocksize; i++) sub[0][i] = sub[0][i] + sub[1][i];
            n_ch = 2;
        } else if (ch_code == 10) {
            /* Mid/Side stereo */
            if (decode_subframe(&br, sub[0], blocksize, sample_size) != 0) goto err;
            if (decode_subframe(&br, sub[1], blocksize, sample_size + 1) != 0) goto err;
            for (int i = 0; i < blocksize; i++) {
                int32_t mid = sub[0][i];
                int32_t side = sub[1][i];
                /* FLAC: mid is stored with lsb dropped, recover */
                int64_t m = ((int64_t)mid << 1) | (side & 1);
                sub[0][i] = (int32_t)((m + side) >> 1);
                sub[1][i] = (int32_t)((m - side) >> 1);
            }
            n_ch = 2;
        } else {
            break;
        }

        /* Frame footer: padding + CRC-16 */
        br_align_byte(&br);
        (void)br_read_bits(&br, 16);

        /* Append to output */
        for (uint32_t c = 0; c < channels; c++) {
            int src_c = (c < (uint32_t)n_ch) ? (int)c : 0;
            for (int i = 0; i < blocksize; i++) {
                if (out->n_samples + i >= total_samples + 1024) break;
                out->samples[c][out->n_samples + i] = sub[src_c][i];
            }
        }
        out->n_samples += blocksize;
        if (out->n_samples >= total_samples) break;
    }

    if (out->n_samples > total_samples) out->n_samples = total_samples;

    for (uint32_t c = 0; c < channels; c++) free(sub[c]);
    free(buf);
    return 0;

err:
    for (uint32_t c = 0; c < channels; c++) if (sub[c]) free(sub[c]);
    free(buf);
    return -1;
}

void flac_free(FlacDecoded *d) {
    if (d->samples) {
        for (uint32_t c = 0; c < d->channels; c++) free(d->samples[c]);
        free(d->samples);
        d->samples = NULL;
    }
}
