#include "wavwrite.h"
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>

static void write_u32le(FILE *f, uint32_t v) {
    uint8_t b[4] = { v & 0xff, (v >> 8) & 0xff, (v >> 16) & 0xff, (v >> 24) & 0xff };
    fwrite(b, 1, 4, f);
}
static void write_u16le(FILE *f, uint16_t v) {
    uint8_t b[2] = { v & 0xff, (v >> 8) & 0xff };
    fwrite(b, 1, 2, f);
}

int wav_write_file(const char *path, const FlacDecoded *d) {
    uint32_t sample_rate = d->sample_rate;
    uint32_t channels = d->channels;
    uint32_t bps = d->bps;
    uint32_t bytes_per_sample = (bps + 7) / 8;
    uint32_t block_align = channels * bytes_per_sample;
    uint32_t byte_rate = sample_rate * block_align;

    uint64_t n = d->n_samples;
    uint32_t data_size = (uint32_t)(n * block_align);

    /* Compose ISFT metadata chunk: "Lavf62.9.101" (ffmpeg internal) */
    const char *encoder = "Lavf62.9.101";
    uint32_t encoder_len = (uint32_t)strlen(encoder) + 1; /* include null */
    uint32_t encoder_pad = encoder_len & 1; /* pad to even */
    /* LIST chunk body: "INFO" + "ISFT" + size(4) + data + pad */
    uint32_t list_body = 4 + 4 + 4 + encoder_len + encoder_pad;

    uint32_t total_body = 4 /* WAVE */
                        + 4 + 4 + 16 /* fmt header + 16 bytes */
                        + 4 + 4 + list_body /* LIST chunk */
                        + 4 + 4 + data_size; /* data chunk */
    /* Note: for PCM, data chunk might also need padding if odd, but block_align*n is even here */

    FILE *f = fopen(path, "wb");
    if (!f) { perror("fopen"); return -1; }

    fwrite("RIFF", 1, 4, f);
    write_u32le(f, total_body);
    fwrite("WAVE", 1, 4, f);

    /* fmt chunk */
    fwrite("fmt ", 1, 4, f);
    write_u32le(f, 16);
    write_u16le(f, 1); /* PCM */
    write_u16le(f, (uint16_t)channels);
    write_u32le(f, sample_rate);
    write_u32le(f, byte_rate);
    write_u16le(f, (uint16_t)block_align);
    write_u16le(f, (uint16_t)bps);

    /* LIST chunk */
    fwrite("LIST", 1, 4, f);
    write_u32le(f, list_body);
    fwrite("INFO", 1, 4, f);
    fwrite("ISFT", 1, 4, f);
    write_u32le(f, encoder_len);
    fwrite(encoder, 1, encoder_len - 1, f);
    uint8_t zero = 0;
    fwrite(&zero, 1, 1, f); /* null terminator */
    for (uint32_t i = 0; i < encoder_pad; i++) fwrite(&zero, 1, 1, f);

    /* data chunk */
    fwrite("data", 1, 4, f);
    write_u32le(f, data_size);
    /* Interleave samples */
    for (uint64_t i = 0; i < n; i++) {
        for (uint32_t c = 0; c < channels; c++) {
            int32_t s = d->samples[c][i];
            if (bps == 8) {
                uint8_t b = (uint8_t)(s + 128);
                fwrite(&b, 1, 1, f);
            } else if (bps == 16) {
                write_u16le(f, (uint16_t)(int16_t)s);
            } else if (bps == 24) {
                uint8_t b[3] = { s & 0xff, (s >> 8) & 0xff, (s >> 16) & 0xff };
                fwrite(b, 1, 3, f);
            } else if (bps == 32) {
                write_u32le(f, (uint32_t)s);
            } else {
                /* pad to next byte */
                write_u16le(f, (uint16_t)(int16_t)s);
            }
        }
    }

    fclose(f);
    return 0;
}
